    #[inline]
    pub fn unwrap_or(self, default: TokenType) -> TokenType {
        if self.is_none() {
            #[cold]
            pub const fn cold() {}
            cold();
            default
        } else {
            self
        }
    }
    #[inline]
    pub fn is_none(&self) -> bool {
        *self == TokenType::TK_NONE
    }
